NEW_FILES = {'tests/test_selling_room_lamps.py': '"""A selling room keeps a shop\'s lamp density however big it is (0.274.0) -- pure, no bpy.\n\nThe walker, 2026-10-26, in seed 9205\'s supermarket: "far too dark in teh super market", and the comps after it --\n"shiny floor, bright lights, isles, glowing freezer section" (the factory\'s docs/reference/GROCERY_STORE_COMPS.md).\nEvery room was held to twelve lamps whatever its size, so the supermarkets\' sales floors were lit at 88 to 92 m2 a\nlamp against the delis\' 25 (the factory\'s docs/findings/selling_hall_lights/census.py). A room whose id sells takes its\ncap from its area, one lamp a `lights._SELLING_M2_PER_LAMP`; every other room keeps the library\'s caps.\n\nFAILS ON 0.273.0: `room_caps` does not exist, and supermarket_a01\'s sales floor lays 12 lamps.\n\nRun:  python -m pytest tests/test_selling_room_lamps.py\n"""\nimport os\n\nimport lights\nimport spec_loader\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nCAP, SH, WALL = 0.3, 4.5, 0.3\n\n\ndef _lamps(room):\n    anchors = lights.derive_light_anchors([room], [], SH, cap_thick=CAP, wall_thick=WALL)\n    return sum(a["row"]["count"] for a in anchors if a["type"] == "fluorescent" and a["room"] == room["id"])\n\n\ndef _room(rid, w, d, role="public_entry"):\n    return {"id": rid, "story": 0, "bounds": [0.0, 0.0, w, d], "role": role, "center": [w / 2, d / 2, 0.0]}\n\n\ndef test_a_selling_rooms_cap_is_its_area_at_a_shops_density():\n    assert lights.room_caps(_room("sales_floor", 44.0, 24.0), [0.0, 0.0, 44.0, 24.0]) == (42, 42, 42)\n    # never fewer than the library\'s twelve\n    assert lights.room_caps(_room("sales_floor", 10.0, 10.0), [0.0, 0.0, 10.0, 10.0]) == (12, 12, 12)\n    # a room that does not sell keeps the library\'s caps, however big\n    caps = (lights._MAX_ROWS, lights._MAX_FIXTURES, lights._MAX_LAMPS_ROOM)\n    assert lights.room_caps(_room("concourse", 44.0, 24.0), [0.0, 0.0, 44.0, 24.0]) == caps\n    assert lights.room_caps(_room("stockroom", 44.0, 24.0), [0.0, 0.0, 44.0, 24.0]) == caps\n\n\ndef test_a_supermarkets_sales_floor_is_lit_like_a_shop():\n    """WOOD\'s rule decides how many it asks for; the cap only bounds it. supermarket_a01\'s 44 x 24 m floor under a\n    4.1 m ceiling asks five rows of nine at 4.65 m and gets five of eight -- 40 lamps, 26.4 m2 a lamp."""\n    spec = spec_loader.load_spec(os.path.join(HERE, "specs", "supermarket_a01.json"))\n    room = next(r for r in spec.rooms if r.id == "sales_floor")\n    b = list(room.bounds)\n    n = _lamps(_room("sales_floor", b[2] - b[0], b[3] - b[1]))\n    area = (b[2] - b[0]) * (b[3] - b[1])\n    assert n == 40, n\n    assert area / n <= lights._SELLING_M2_PER_LAMP * 1.1, area / n\n\n\ndef test_a_hall_that_does_not_sell_keeps_twelve():\n    assert _lamps(_room("concourse", 44.0, 24.0)) == lights._MAX_LAMPS_ROOM\n'}
CHANGELOG = '## [0.274.0] - a selling room keeps a shop\'s lamp density, however big it is\n\nThe walker, 2026-10-26, in seed 9205\'s supermarket: "far too dark in teh super market". Then came the comps: "shiny\nfloor, bright lights, isles, glowing freezer section". They are filed as the factory\'s\ndocs/reference/GROCERY_STORE_COMPS.md: long fluorescent runs 2 to 3 m apart, nothing in shadow.\n\nEvery room was held to twelve lamps, whatever its size (`_MAX_LAMPS_ROOM`, "until the price of more is measured").\nSo the library\'s selling floors got darker as they got bigger. The factory\'s\ndocs/findings/selling_hall_lights/census.py counts it:\n- the shops under 340 m2: 13 to 34 m2 a lamp;\n- the supermarkets: 88 to 92;\n- the market halls: 89 to 104.\n\n### Changed\n- **`lights.room_caps(r, bounds)`**: a room whose id sells takes its lamp cap from its area. "Sells" means\n  `floors.floor_by_use` returns "tile", the same words that tile its floor.\n  - The cap is one lamp per `_SELLING_M2_PER_LAMP` (25.0) and never fewer than twelve. Its rows across and its\n    lamps along are bounded by that cap alone.\n  - 25 m2 is the density the library\'s capped selling rooms of 250 to 300 m2 already had: the delis\'\n    `market_aisles` 25.0, gas_station_a02 23.0, convenience_store_a01 21.1, pharmacy_a01 26.4. A big store is lit\n    like a small one, not brighter.\n  - WOOD\'s spacing, unchanged, decides how many lamps a room asks for. supermarket_a01\'s 44 x 24 m sales floor goes\n    from 3 rows of 4 at 11 m to 5 rows of 8 at 5.5 m: 40 lamps, 26.4 m2 a lamp. market_hall_a01\'s stall floor\n    goes from 10 to 15.\n  - Every other room keeps the library\'s caps.\n- The lamps are baked, so what more of them costs a frame is their fixtures\' draws. The price is in the factory\'s\n  docs/findings/selling_hall_lights/.\n\n### Tests\n- `tests/test_selling_room_lamps.py` (2 of 3 fail on 0.273.0):\n  - the cap\'s derivation;\n  - supermarket_a01 lit at 40 lamps;\n  - a non-selling hall kept at twelve.\n- `test_fixture_rows`\'s many-aisles cap test now names a stockroom, which keeps the library\'s cap.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.273.0', 'Deli Counter 0.274.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
